WITH eligible AS (SELECT s.* FROM orders s WHERE NOT EXISTS (SELECT 1 FROM payments x WHERE x.order_id = s.id AND x.paid_at >= s.order_date)) SELECT DATE_TRUNC('QUARTER', order_date) AS quarter_start, COUNT(CASE WHEN status = 'CANCELLED' THEN 1 END) AS cancelled_count, COUNT(DISTINCT id) AS distinct_ids, ROUND(AVG(amount), 2) AS avg_amount FROM eligible GROUP BY 1 ORDER BY cancelled_count NULLS LAST
